f=go.Figure()
for a in arms[1:]:f.add_trace(go.Bar(name=a,x=['Earlier fold','Later fold'],y=result['comparisons'][a+'_minus_control_shared']['fold_gains']))
f.add_hline(y=0,line_dash='dash');f.update_layout(title='Temporal instability: negative earlier fold, positive later fold',barmode='group');emit(f)

f=go.Figure()
for a in arms[1:]:f.add_trace(go.Bar(name=a,x=['Clicks','Carts','Orders'],y=[result['comparisons'][a+'_minus_control_shared']['net_extra_hits'][k] for k in ['clicks','carts','orders']]))
f.update_layout(title='Net extra hits versus unchanged control',barmode='group');emit(f)

f=go.Figure()
for a in arms:f.add_trace(go.Bar(name=a,x=['Clicks','Carts','Orders'],y=[result['arms'][a]['recall'][k] for k in ['clicks','carts','orders']]))
f.update_layout(title='Recall by objective — full target denominators',barmode='group');emit(f)

f=go.Figure()
for a in arms[1:]:f.add_trace(go.Bar(name=a,x=['Clicks','Carts','Orders'],y=[result['comparisons'][a+'_minus_control_shared']['weighted_contributions'][k] for k in ['clicks','carts','orders']]))
f.update_layout(title='Which target hits caused the pooled score change?',barmode='group');emit(f)
